{
  "findings": [
    {
      "check_id": "CKV_AWS_24",
      "title": "EBS Volume Encryption Disabled",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "HIGH",
      "explanation": "The EBS volume is explicitly configured with 'encrypted = false', leaving data at rest unencrypted and vulnerable to unauthorized access if the underlying storage media is compromised."
    }
  ],
  "patched_code": "resource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n}",
  "fix_summary": "Changed the 'encrypted' attribute from false to true to enable encryption at rest for the EBS volume, complying with security best practices."
}
